package polymorphism.assigment_problems;

import java.util.*;public class CanteenBillingCounter {interface Bill{double total();}static class Student implements Bill{double a;Student(double a){this.a=a;}public double total(){return a*.9;}}static class Staff implements Bill{double a;Staff(double a){this.a=a;}public double total(){return a*.95;}}static class Guest implements Bill{double a;Guest(double a){this.a=a;}public double total(){return a+10;}}public static void main(String[] z){Scanner s=new Scanner(System.in);int n=s.nextInt();double sum=0;for(int i=0;i<n;i++){String t=s.next();double a=s.nextDouble();Bill b=t.equals("STUDENT")?new Student(a):t.equals("STAFF")?new Staff(a):new Guest(a);double v=b.total();System.out.printf(Locale.US,"%s: %.2f%n",t,v);sum+=v;}System.out.printf(Locale.US,"Total: %.2f%n",sum);}}
